package org.jlinalg.cli;

import java.nio.file.*;
import java.util.*;
import org.jlinalg.singlecell.CellPhoneDbStatistics;
import org.jlinalg.singlecell.CellPhoneDbPreparation;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

/** Actual packaged Java preparation of the raw-file original-workflow control families. */
public final class CellPhoneDbPreparationMatrix {
    private CellPhoneDbPreparationMatrix() { }
    private static double number(Object raw)throws Exception{return finite(raw,-Double.MAX_VALUE,Double.MAX_VALUE);}
    private static long id(Object raw)throws Exception{return integer(raw,Long.MIN_VALUE,Long.MAX_VALUE);}
    private static List<String> texts(Object raw)throws Exception{var result=new ArrayList<String>();for(Object value:list(raw))result.add(text(value));return List.copyOf(result);}
    private static String nullable(Object raw)throws Exception{return raw==null?null:text(raw);}
    private static double[][] matrix(Object raw)throws Exception{var rows=list(raw);double[][] result=new double[rows.size()][];for(int i=0;i<rows.size();i++){var row=list(rows.get(i));result[i]=new double[row.size()];for(int j=0;j<row.size();j++)result[i][j]=number(row.get(j));}return result;}
    private static Object values(double[][] matrix){var result=new ArrayList<Object>();for(double[] row:matrix){var next=new ArrayList<Object>();for(double value:row)next.add(Double.isFinite(value)?value:Double.isNaN(value)?"NaN":value>0?"+Inf":"-Inf");result.add(next);}return result;}
    private static Map<String,Object> relation(CellPhoneDbPreparation.Gene gene){var row=new LinkedHashMap<String,Object>();row.put("id_multidata",gene.id());row.put("ensembl",gene.ensembl()==null?"NaN":gene.ensembl());row.put("gene_name",gene.geneName()==null?"NaN":gene.geneName());row.put("hgnc_symbol",gene.hgncSymbol()==null?"NaN":gene.hgncSymbol());return row;}
    private static Map<String,Object> composition(CellPhoneDbPreparation.Composition row){return Map.of("row_id",row.rowId(),"complex_multidata_id",row.complexId(),"protein_multidata_id",row.proteinId(),"total_protein",row.totalProtein());}
    public static void main(String[] args)throws Exception {
        require(args.length==2,"Need complete original raw preparation cases and NEW output directory");Path input=Path.of(args[0]),out=Path.of(args[1]);byte[] original=NextflowFiles.bytes(input,67108864);var root=object(NextflowParameters.parse(NextflowFiles.utf8(original),67108864,4000000));require(!Files.exists(out),"Existing preparation controls protected");Files.createDirectory(out);var results=new ArrayList<Object>();var ledgers=new LinkedHashMap<String,Object>();var sourceErrors=new ArrayList<String>();long operations=0;
        for(Object raw:list(root.get("cases"))){var c=object(raw);String name=text(c.get("id"));if(c.containsKey("expected_original_error")){sourceErrors.add(name);continue;}var counts=new CellPhoneDbPreparation.Counts(texts(c.get("raw_genes")),texts(c.get("raw_cells")),matrix(c.get("raw_expression")));var metadata=new CellPhoneDbPreparation.Metadata(texts(c.get("meta_cells")),texts(c.get("meta_cell_types")));var genes=new ArrayList<CellPhoneDbPreparation.Gene>();for(Object item:list(c.get("gene_rows"))){var row=object(item);genes.add(new CellPhoneDbPreparation.Gene(id(row.get("id_multidata")),nullable(row.get("ensembl")),nullable(row.get("gene_name")),nullable(row.get("hgnc_symbol"))));}var composition=new ArrayList<CellPhoneDbPreparation.Composition>();for(Object item:list(c.get("composition"))){var row=object(item);composition.add(new CellPhoneDbPreparation.Composition(id(row.get("row_id")),id(row.get("complex_multidata_id")),id(row.get("protein_multidata_id")),id(row.get("total_protein"))));}var interactions=new ArrayList<CellPhoneDbStatistics.Interaction>();for(Object item:list(c.get("interactions"))){var row=object(item);interactions.add(new CellPhoneDbStatistics.Interaction(text(row.get("id")),id(row.get("first")),id(row.get("second"))));}
            var result=CellPhoneDbPreparation.prepare(counts,metadata,genes,CellPhoneDbPreparation.Identifier.valueOf(text(c.get("counts_data")).toUpperCase(Locale.ROOT)),composition,interactions,CellPhoneDbPreparation.Limits.defaults());var report=new LinkedHashMap<String,Object>();report.put("preprocessed_genes",result.preprocessedGenes());report.put("preprocessed_cells",result.preprocessedCells());report.put("preprocessed_expression",values(result.preprocessedExpression()));report.put("metadata_cells",metadata.cells());report.put("metadata_cell_types",metadata.cellTypes());report.put("mapped_features",result.mappedFeatures());report.put("cells",result.cells());report.put("mapped_expression",values(result.mappedExpression()));report.put("relations",result.relations().stream().map(r->relation(r.gene())).toList());report.put("filtered_interaction_ids",result.filteredInteractions().stream().map(CellPhoneDbStatistics.Interaction::id).toList());report.put("filtered_features",result.filteredFeatures());report.put("filtered_expression",values(result.filteredExpression()));report.put("filtered_composition",result.filteredComposition().stream().map(CellPhoneDbPreparationMatrix::composition).toList());report.put("complex_map",result.complexMap().stream().map(row->Map.of("id",row.id(),"rows",row.rows())).toList());report.put("aligned_cell_types",result.alignedCellTypes());results.add(Map.of("id",name,"preparation",report));
            var ledger=new LinkedHashMap<String,Object>();ledger.put("removed_cells",result.removedCells());ledger.put("zero_proteins",result.zeroProteins());ledger.put("gene_ledger",result.geneLedger().stream().map(row->Map.of("source_row",row.sourceRow(),"original_gene",row.originalGene(),"mapped_ids",row.mappedIds())).toList());ledger.put("casting_ledger",result.castingLedger().stream().map(row->Map.of("source_row",row.sourceRow(),"cell_column",row.cellColumn(),"original",row.original(),"source_float32",Double.isFinite(row.sourceFloat32())?row.sourceFloat32():row.sourceFloat32()>0?"+Inf":"-Inf")).toList());ledger.put("relation_rows",result.relations().stream().map(row->Map.of("source_row",row.sourceRow(),"gene_row",row.geneRow())).toList());ledger.put("warnings",result.warnings());ledgers.put(name,ledger);operations+=result.operations();
        }
        var good=new CellPhoneDbPreparation.Counts(List.of("g1","g2"),List.of("x","y"),new double[][]{{1,2},{3,4}});var meta=new CellPhoneDbPreparation.Metadata(List.of("y","x"),List.of("B","A"));var genes=List.of(new CellPhoneDbPreparation.Gene(1,"e1","g1","h1"),new CellPhoneDbPreparation.Gene(2,"e2","g2","h2"));var interactions=List.of(new CellPhoneDbStatistics.Interaction("I",1,2));var limits=CellPhoneDbPreparation.Limits.defaults();var rejected=new ArrayList<String>();
        reject("negative-raw-expression",()->run(new CellPhoneDbPreparation.Counts(good.genes(),good.cells(),new double[][]{{-1,2},{3,4}}),meta,genes,interactions,limits),rejected);
        reject("nonfinite-raw-expression",()->run(new CellPhoneDbPreparation.Counts(good.genes(),good.cells(),new double[][]{{Double.NaN,2},{3,4}}),meta,genes,interactions,limits),rejected);
        reject("ragged-raw-expression",()->run(new CellPhoneDbPreparation.Counts(good.genes(),good.cells(),new double[][]{{1},{3,4}}),meta,genes,interactions,limits),rejected);
        reject("duplicate-original-cell",()->run(new CellPhoneDbPreparation.Counts(good.genes(),List.of("x","x"),good.expression()),meta,genes,interactions,limits),rejected);
        reject("duplicate-metadata-cell",()->run(good,new CellPhoneDbPreparation.Metadata(List.of("x","x"),List.of("A","B")),genes,interactions,limits),rejected);
        reject("missing-metadata-cell",()->run(good,new CellPhoneDbPreparation.Metadata(List.of("x","absent"),List.of("A","B")),genes,interactions,limits),rejected);
        reject("ragged-metadata-axis",()->run(good,new CellPhoneDbPreparation.Metadata(List.of("x","y"),List.of("A")),genes,interactions,limits),rejected);
        reject("all-unmapped-no-synonym-repair",()->run(new CellPhoneDbPreparation.Counts(List.of("unknown","alias"),good.cells(),good.expression()),meta,genes,interactions,limits),rejected);
        reject("nonpositive-composition-total",()->new CellPhoneDbPreparation.Composition(1,3,1,0),rejected);
        reject("duplicate-composition-row-id",()->CellPhoneDbPreparation.prepare(good,meta,genes,CellPhoneDbPreparation.Identifier.GENE_NAME,List.of(new CellPhoneDbPreparation.Composition(1,3,1,1),new CellPhoneDbPreparation.Composition(1,3,2,1)),interactions,limits),rejected);
        reject("duplicate-interaction-identity",()->run(good,meta,genes,List.of(interactions.get(0),interactions.get(0)),limits),rejected);
        reject("matrix-capacity-before-allocation",()->run(good,meta,genes,interactions,new CellPhoneDbPreparation.Limits(10,10,10,10,10,10,1,1000)),rejected);
        reject("many-to-many-join-capacity",()->run(good,meta,genes,interactions,new CellPhoneDbPreparation.Limits(10,10,10,10,10,1,1000,1000)),rejected);
        reject("operation-capacity",()->run(good,meta,genes,interactions,new CellPhoneDbPreparation.Limits(10,10,10,10,10,10,1000,1)),rejected);
        Thread.currentThread().interrupt();try{reject("thread-cancellation",()->run(good,meta,genes,interactions,limits),rejected);}finally{Thread.interrupted();}
        var protectedInput=good.expression();protectedInput[0][0]=999;require(good.expression()[0][0]==1,"Prepared raw matrix alias changed original values");var protectedResult=run(good,meta,genes,interactions,limits);double expected=protectedResult.filteredExpression()[0][0];protectedResult.filteredExpression()[0][0]=888;protectedResult.mappedExpression()[0][0]=888;protectedResult.preprocessedExpression()[0][0]=888;protectedResult.prepared().expression()[0][0]=888;require(protectedResult.filteredExpression()[0][0]==expected&&protectedResult.mappedExpression()[0][0]==1&&protectedResult.preprocessedExpression()[0][0]==1&&protectedResult.prepared().expression()[0][0]==expected,"Returned preparation matrix alias changed retained values");
        require(Arrays.equals(original,NextflowFiles.bytes(input,67108864)),"Original raw cases changed");NextflowFiles.writeJson(out.resolve("results.json"),Map.of("cases",results));NextflowFiles.writeJson(out.resolve("ledgers.json"),ledgers);NextflowFiles.writeJson(out.resolve("COMPLETED.json"),Map.of("status","PASS_NATIVE_CELLPHONEDB_TYPED_PREPARATION_ONLY","cases",results.size(),"expected_native_rejections",rejected,"original_full_workflow_error_controls",sourceErrors,"defensive_copy_controls",true,"operations",operations,"implementation_credit",false,"whole_goal_complete",false));
    }
    private static CellPhoneDbPreparation.Result run(CellPhoneDbPreparation.Counts counts,CellPhoneDbPreparation.Metadata metadata,List<CellPhoneDbPreparation.Gene> genes,List<CellPhoneDbStatistics.Interaction> interactions,CellPhoneDbPreparation.Limits limits){return CellPhoneDbPreparation.prepare(counts,metadata,genes,CellPhoneDbPreparation.Identifier.GENE_NAME,List.of(),interactions,limits);}
    @FunctionalInterface private interface Check {Object run()throws Exception;}
    private static void reject(String name,Check action,List<String> rejected)throws Exception{boolean failed=false;try{action.run();}catch(IllegalArgumentException expected){failed=true;}require(failed,"Invalid preparation family admitted: "+name);rejected.add(name);}
}
